# Purchase-plan allocations and explicitly visible concurrent liabilities.
build_bnpl_obligation_features<-function(plans,installments,events,provider_coverage,customer_id,as_of,information_cutoff,lookback_days,near_term_days,currency,context=NULL){times<-.cr_rb_window(as_of,information_cutoff,lookback_days,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;days<-times$days;start<-times$start;.cr_rf_text(customer_id,'customer_id');.cr_rf_text(currency,'currency');near<-.cr_data_days(near_term_days,'near_term_days',1);if(near>as.numeric(as.Date('9999-12-31')-anchor)) .cr_error('RETAIL_DATE','Near-term horizon exceeds supported calendar');end<-anchor+near;coverage<-.cr_rf_coverage(provider_coverage,cutoff);if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from BNPL currency');plan_release<-.cr_rf_releases(plans,'plan_id',cutoff,'purchase plans');visible<-list()
 for(row in plan_release$rows){.cr_data_required(row,c('customer_id','provider_id','purchased_at','currency','schedule_complete'));if(!all(c('closed_at','refinances_plan_id')%in%names(row))) .cr_error('RETAIL_CONTRACT','Plan closed_at and refinances_plan_id must be explicit nullable fields');if(!is.logical(row$schedule_complete)||length(row$schedule_complete)!=1||is.na(row$schedule_complete)) .cr_error('RETAIL_COVERAGE','Each plan requires explicit schedule completeness');purchased<-.cr_data_date(row$purchased_at,'purchased_at');closed<-if(is.null(row$closed_at))NULL else .cr_data_date(row$closed_at,'closed_at');known<-.cr_data_date(row$known_at,'known_at');if(purchased>known||(!is.null(closed)&&!(purchased<=closed&&closed<=known))) .cr_error('RETAIL_DATE','Purchase/actual closure must be known after occurrence');if(row$customer_id!=customer_id||row$currency!=currency||!(row$provider_id%in%unlist(coverage$sources))) .cr_error('RETAIL_ENTITY','Plans must match customer, currency and declared providers');if(purchased<=anchor)visible[[row$plan_id]]<-row}
 for(row in visible)if(!is.null(row$refinances_plan_id)){previous<-visible[[row$refinances_plan_id]];if(is.null(previous)||previous$plan_id==row$plan_id||previous$purchased_at>=row$purchased_at) .cr_error('RETAIL_PLAN','Explicit refinanced plan must be an earlier visible plan')};installment_release<-.cr_rf_releases(installments,'installment_id',cutoff,'installments');due<-list();for(row in installment_release$rows){.cr_data_required(row,c('plan_id','due_at','amount','currency'));plan<-visible[[row$plan_id]];if(is.null(plan)) .cr_error('RETAIL_PLAN','Visible installment lacks a visible customer plan');if(.cr_data_date(row$due_at,'due_at')<.cr_data_date(plan$purchased_at,'purchased_at')||row$currency!=currency) .cr_error('RETAIL_DATE','Installment date/currency incompatible with purchase plan');.cr_rf_number(row$amount,'installment amount',0);due[[row$installment_id]]<-row}
 event_release<-.cr_rf_releases(events,'event_id',cutoff,'plan events');visible_events<-list();financial<-c('PAYMENT','MERCHANT_REFUND','PAYMENT_REVERSAL','REFUND_REVERSAL');for(row in event_release$rows){.cr_data_required(row,c('plan_id','occurred_at','kind','amount','currency'));if(!all(c('installment_id','related_event_id')%in%names(row))) .cr_error('RETAIL_CONTRACT','Event installment and related event must be explicit nullable fields');plan<-visible[[row$plan_id]];occurred<-.cr_data_date(row$occurred_at,'occurred_at');if(is.null(plan)||row$currency!=currency) .cr_error('RETAIL_PLAN','Visible event must match a visible plan and currency');if(!(.cr_data_date(plan$purchased_at,'purchased_at')<=occurred&&occurred<=.cr_data_date(row$known_at,'known_at'))) .cr_error('RETAIL_DATE','Plan-event occurrence/receipt chronology invalid');.cr_rf_number(row$amount,'event amount',0);if(!(row$kind%in%c(financial,'DISPUTE_OPEN','DISPUTE_CLOSE'))) .cr_error('RETAIL_PLAN','Unsupported plan event');if(row$kind%in%financial){if(!is.null(plan$closed_at)&&occurred>.cr_data_date(plan$closed_at,'closed_at')) .cr_error('RETAIL_PLAN','Financial event follows actual plan closure; correct closure or separate customer cashflows');installment<-if(is.null(row$installment_id))NULL else due[[row$installment_id]];if(is.null(installment)||installment$plan_id!=row$plan_id) .cr_error('RETAIL_PLAN','Financial events require explicit same-plan installment allocation')}else if(row$amount!=0) .cr_error('RETAIL_PLAN','Dispute events do not themselves reduce debt; use an allocated merchant refund');if(occurred<=anchor)visible_events[[row$event_id]]<-row}
 settlements<-refunds<-setNames(rep(list(numeric()),length(due)),names(due));reversals<-list();open_disputes<-list();closed_disputes<-character();for(key in sort(names(visible_events))){row<-visible_events[[key]];kind<-row$kind;related<-row$related_event_id;if(kind%in%c('PAYMENT','MERCHANT_REFUND')){if(!is.null(related)) .cr_error('RETAIL_PLAN','Original financial event must not identify a reversed event');if(kind=='PAYMENT')settlements[[row$installment_id]]<-c(settlements[[row$installment_id]],row$amount)else refunds[[row$installment_id]]<-c(refunds[[row$installment_id]],row$amount)}else if(kind%in%c('PAYMENT_REVERSAL','REFUND_REVERSAL')){original<-if(is.null(related))NULL else visible_events[[related]];expected<-if(kind=='PAYMENT_REVERSAL')'PAYMENT'else 'MERCHANT_REFUND';if(is.null(original)||original$kind!=expected||original$installment_id!=row$installment_id||original$occurred_at>row$occurred_at) .cr_error('RETAIL_REVERSAL','Plan reversal must match an earlier allocated original event');reversals[[related]]<-c(reversals[[related]],row$amount);if(kind=='PAYMENT_REVERSAL')settlements[[row$installment_id]]<-c(settlements[[row$installment_id]],-row$amount)else refunds[[row$installment_id]]<-c(refunds[[row$installment_id]],-row$amount)}else if(kind=='DISPUTE_OPEN'){if(!is.null(related)) .cr_error('RETAIL_PLAN','Dispute opening cannot identify a closed dispute');open_disputes[[key]]<-row$plan_id}else{original<-if(is.null(related))NULL else visible_events[[related]];if(is.null(original)||original$kind!='DISPUTE_OPEN'||original$plan_id!=row$plan_id||original$occurred_at>row$occurred_at||related%in%closed_disputes) .cr_error('RETAIL_PLAN','Dispute closure needs one earlier open dispute on the same plan');closed_disputes<-c(closed_disputes,related)}}
 for(key in names(reversals))if(.cr_loss_sum(reversals[[key]])>visible_events[[key]]$amount) .cr_error('RETAIL_REVERSAL','Plan reversal amounts exceed original event');outputs<-list();plan_outstanding<-setNames(rep(list(numeric()),length(visible)),names(visible));near_cashflows<-list();overdue<-due_today<-numeric();for(row in .cr_rf_sort(unname(due),c('due_at','installment_id'))){key<-row$installment_id;paid<-.cr_loss_sum(settlements[[key]]);refunded<-.cr_loss_sum(refunds[[key]]);remaining<-.cr_loss_sum(c(row$amount,-paid,-refunded));if(remaining<0) .cr_error('RETAIL_PLAN','Net allocated payments and refunds exceed installment; supply separate customer cash refund outside debt reduction');plan_outstanding[[row$plan_id]]<-c(plan_outstanding[[row$plan_id]],remaining);d<-.cr_data_date(row$due_at,'due_at');if(d<anchor)overdue<-c(overdue,remaining)else if(d==anchor)due_today<-c(due_today,remaining)else if(d<=end)near_cashflows[[row$due_at]]<-c(near_cashflows[[row$due_at]],remaining);outputs[[length(outputs)+1L]]<-list(installment_id=key,plan_id=row$plan_id,due_at=row$due_at,contractual_amount=row$amount,net_paid=paid,net_merchant_refund=refunded,outstanding=remaining)}
 plan_summary<-list();for(key in sort(names(visible))){row<-visible[[key]];amount<-.cr_loss_sum(plan_outstanding[[key]]);closed<-!is.null(row$closed_at)&&.cr_data_date(row$closed_at,'closed_at')<=anchor;if(closed&&amount!=0) .cr_error('RETAIL_PLAN','Closed plan retains unpaid supplied installments; resolve payments/refunds or residual liability explicitly');plan_summary[[length(plan_summary)+1L]]<-list(plan_id=key,provider_id=row$provider_id,purchased_at=row$purchased_at,closed_at=row$closed_at,active=!closed,schedule_complete=row$schedule_complete,known_outstanding=amount,installment_count=length(plan_outstanding[[key]]),refinances_plan_id=row$refinances_plan_id)}
 concurrency<-list();for(offset in seq_len(days)){d<-as.character(start+offset);active<-Filter(function(row)row$purchased_at<=d&&(is.null(row$closed_at)||d<row$closed_at),visible);concurrency[[length(concurrency)+1L]]<-list(date=d,known_active_plan_count=length(active),known_active_provider_count=length(unique(vapply(active,`[[`,character(1),'provider_id'))))};new<-Filter(function(row)start<.cr_data_date(row$purchased_at,'purchased_at')&&.cr_data_date(row$purchased_at,'purchased_at')<=anchor,visible);known_total<-.cr_loss_sum(vapply(plan_summary,`[[`,numeric(1),'known_outstanding'));complete<-coverage$status=='COMPLETE'&&all(vapply(plan_summary,function(row)row$schedule_complete&&row$installment_count>0,logical(1)));first<-if(length(visible)).cr_rf_sort(unname(visible),c('purchased_at','plan_id'))[[1]]$plan_id else NULL
 .cr_result(list(customer_id=customer_id,as_of=as_of,information_cutoff=information_cutoff,currency=currency,provider_coverage=coverage,coverage_complete=complete,active_plan_count=sum(vapply(plan_summary,`[[`,logical(1),'active')),plans_with_positive_outstanding=sum(vapply(plan_summary,function(row)row$known_outstanding>0,logical(1))),maximum_known_concurrent_plans=max(vapply(concurrency,`[[`,numeric(1),'known_active_plan_count')),maximum_known_concurrent_providers=max(vapply(concurrency,`[[`,numeric(1),'known_active_provider_count')),new_plan_count=length(new),repeat_purchase_count=sum(vapply(new,function(row)row$plan_id!=first,logical(1))),explicit_refinancing_count=sum(vapply(new,function(row)!is.null(row$refinances_plan_id),logical(1))),open_dispute_count=length(setdiff(names(open_disputes),closed_disputes)),known_outstanding=known_total,total_outstanding=if(complete)known_total else NULL,known_overdue_amount=.cr_loss_sum(overdue),known_due_today=.cr_loss_sum(due_today),near_term_days=near,known_near_term_due=.cr_loss_sum(unlist(near_cashflows,use.names=FALSE)),near_term_cashflows=lapply(sort(names(near_cashflows)),function(k)list(due_at=k,known_due=.cr_loss_sum(near_cashflows[[k]]))),plans=plan_summary,installments=outputs,daily_known_concurrency=concurrency),'retail_features.build_bnpl_obligation_features',currency,ctx,diagnostics=list(excluded_plan_releases=plan_release$excluded,excluded_installment_releases=installment_release$excluded,excluded_event_releases=event_release$excluded),limitations=list('Provider completeness is supplied, never inferred from a bureau or an empty file. Financial events require explicit installment allocation, without guessed FIFO. Disputes are separate nonfinancial events and do not imply default or suspend debt automatically. Refunds reduce only explicitly allocated unpaid installments; excess customer refunds are separate cashflows. Active-plan overlap uses actual purchase/closure dates visible at this cutoff, not assumed contractual maturity; it is a retrospective known-history description. Repeated purchases are not inferred refinancing; refinancing needs an explicit earlier-plan link.'))}
